def transform(data,reverse=False):
 text=data.decode()
 pairs=[(b,a) for a,b in reversed(patch['changes'])] if reverse else patch['changes']
 for a,b in pairs:
  assert text.count(a)==1,'UI patch anchor drift'
  text=text.replace(a,b,1)
 return text.encode()
old=current if digest(current)==patch['before'] else transform(current,True)
new=transform(old)
assert digest(old)==patch['before'] and digest(new)==patch['after'],'UI hash mismatch'
files[js_path]={'old':old,'new':new}
previous={}
for p,d in files.items():
 previous[p]=read(p);assert previous[p] in (d['old'],d['new']),'source drift: '+p
 if p.endswith('.py'): compile(d['new'],p,'exec')
timers=['gb-slot-telemetry-slot1.timer','gb-slot-telemetry-slot2.timer']
services=['gb-slot-telemetry-slot1.service','gb-slot-telemetry-slot2.service']
def state(verb,unit):
 result=subprocess.run(['/usr/bin/systemctl',verb,unit],capture_output=True,text=True,timeout=10)
 return result.stdout.strip()
prior={u:(state('is-enabled',u),state('is-active',u)) for u in timers+services}
for u,(enabled,active) in prior.items():
 assert enabled in ('enabled','disabled','static','not-found') and active in ('active','inactive'),'unsupported/busy unit state: '+u
assert state('is-active','gb-ops-monitor-web.service')=='active','monitor web must already be active'
assert state('is-active','gb-ops-monitor-writer.service')=='inactive','writer currently busy'
