def write(p,data):
 if data is None:
  if os.path.lexists(p): os.unlink(p)
  return
 fd,tmp=tempfile.mkstemp(prefix='.telemetry-install-',dir=str(Path(p).parent))
 try:
  with os.fdopen(fd,'wb') as f:
   os.fchmod(f.fileno(),0o644);os.fchown(f.fileno(),0,0);f.write(data);f.flush();os.fsync(f.fileno())
  os.replace(tmp,p)
 finally:
  if os.path.lexists(tmp):os.unlink(tmp)
def system(*args):subprocess.run(['/usr/bin/systemctl',*args],check=True,timeout=40)
timers=['gb-slot-telemetry-slot1.timer','gb-slot-telemetry-slot2.timer']
services=['gb-slot-telemetry-slot1.service','gb-slot-telemetry-slot2.service']
changed=[]
